function Write-KV([string]$Name,[object]$Value) { Write-Output ($Name+'='+[string]$Value) }
function Get-Sha256([string]$Path) { return (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant() }
function Write-AtomicText([string]$Path,[string]$Text) {
    $parent=Split-Path -Parent $Path
    if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null}
    $tmp=$Path+'.tmp.'+[guid]::NewGuid().ToString('N')
    [IO.File]::WriteAllText($tmp,$Text,(New-Object Text.UTF8Encoding($false)))
    Move-Item -LiteralPath $tmp -Destination $Path -Force
}
function Write-AtomicJson([string]$Path,[object]$Value) { Write-AtomicText $Path ($Value|ConvertTo-Json -Depth 40) }

function Assert-ProductionTarget {
    param([string]$Root=$script:ExpectedRoot,[int]$Port=$script:ExpectedPort,[string]$App=$script:ExpectedApp)
    if($Root -ne $script:ExpectedRoot -or $Port -ne $script:ExpectedPort -or $App -ne $script:ExpectedApp){throw 'PRODUCTION_TARGET_GUARD_FAILED'}
    if($Port -in $script:ForbiddenPorts -or $App -match [regex]::Escape($script:ForbiddenApp)){throw 'FORBIDDEN_TARGET_GUARD_FAILED'}
    return $true
}
function Assert-SimulationTarget {
    param([string]$Root,[int]$Port,[string]$App)
    $full=[IO.Path]::GetFullPath($Root);$prefix=([IO.Path]::GetFullPath($script:SimulationPrefix)).TrimEnd('\')+'\'
    if($full -ne $prefix.TrimEnd('\') -and -not $full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'SIMULATION_CONTEXT_ROOT_GUARD_FAILED'}
    if($full -match '(?i)gaming_marketplace|\\staging(?:\\|$)' -or $full -eq $script:ExpectedRoot){throw 'SIMULATION_CONTEXT_PRODUCTION_PATH_GUARD_FAILED'}
    if($Port -in @($script:ExpectedPort,8501,8504) -or $Port -lt 1024 -or $Port -gt 65535){throw 'SIMULATION_CONTEXT_FORBIDDEN_PORT_GUARD_FAILED'}
    if($App -match '(?i)app_gaming_marketplace|caddy'){throw 'SIMULATION_CONTEXT_APP_GUARD_FAILED'}
    return $true
}
function Assert-Context([object]$Context) {
    if($Context.Mode -eq 'PRODUCTION'){Assert-ProductionTarget $Context.Root $Context.Port $Context.AppPath|Out-Null}
    elseif($Context.Mode -eq 'SIMULATION'){Assert-SimulationTarget $Context.Root $Context.Port $Context.AppPath|Out-Null}
    else{throw 'UNKNOWN_EXECUTION_CONTEXT'}
    if($Context.Port -in $script:ForbiddenPorts -or $Context.AppPath -match [regex]::Escape($script:ForbiddenApp)){throw 'FORBIDDEN_TARGET_GUARD_FAILED'}
}
function Assert-Approval([switch]$Execute,[string]$Actual,[string]$Expected){if($Execute -and $Actual -ne $Expected){throw 'APPROVAL_PHRASE_REQUIRED'}}

function Get-SafeEnv([string]$Path) {
    $out=@{}
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return $out}
    foreach($line in Get-Content -LiteralPath $Path){
        if($line -match '^\s*export\s+'){$line=$line -replace '^\s*export\s+',''}
        if($line -match '^\s*([^#=][^=]*)=(.*)$'){$k=$Matches[1].Trim();$v=$Matches[2].Trim();if(($v.StartsWith('"') -and $v.EndsWith('"')) -or ($v.StartsWith("'") -and $v.EndsWith("'"))){$v=$v.Substring(1,$v.Length-2)};$out[$k]=$v}
    }
    return $out
}
function Get-DatabaseEnvironment([string]$EnvPath,[switch]$Required) {
    $raw=Get-SafeEnv $EnvPath;$map=@{PGHOST='POSTGRES_HOST';PGPORT='POSTGRES_PORT';PGUSER='POSTGRES_USER';PGPASSWORD='POSTGRES_PASSWORD';PGDATABASE='POSTGRES_DB'};$out=@{}
    foreach($k in $map.Keys){$source=$map[$k];if($raw.ContainsKey($source) -and [string]$raw[$source] -ne ''){$out[$k]=[string]$raw[$source]}elseif($Required){throw ('REQUIRED_DB_ENV_MISSING:'+ $source)}};return $out
}
function Get-PostgresTools {
    $out=@{}
    foreach($n in @('pg_dump','pg_restore','psql')){
        $c=Get-Command ($n+'.exe') -ErrorAction SilentlyContinue
        if(-not $c){$c=Get-Command $n -ErrorAction SilentlyContinue}
        if(-not $c){foreach($p in @('C:\Program Files\PostgreSQL\18\bin\'+$n+'.exe','C:\Program Files\PostgreSQL\17\bin\'+$n+'.exe')){if(Test-Path -LiteralPath $p -PathType Leaf){$c=Get-Item $p;break}}}
        if($c){if($c.PSObject.Properties.Name -contains 'Source' -and $c.Source){$out[$n]=$c.Source}else{$out[$n]=$c.FullName}}
    }
    return $out
}
function Get-ToolVersion([string]$Path){if(-not $Path){return ''};try{return ((& $Path '--version' 2>&1)|Select-Object -First 1).ToString().Trim()}catch{return ''}}

function New-ProductionExecutionContext {
    param([hashtable]$Arguments)
    Assert-ProductionTarget|Out-Null
    return [pscustomobject]@{Mode='PRODUCTION';Root=$script:ExpectedRoot;RuntimeRoot=$script:ExpectedRuntimeRoot;AppPath=$script:ExpectedApp;Port=8502;EnvPath=(Join-Path $script:ExpectedRoot '.env');DataRoot=(Join-Path $script:ExpectedRoot 'streamlit_opensea_sales\data_opensea_sales');RepoRoot=$script:ExpectedRoot;ReleaseRoot=$Arguments.ReleaseRoot;ReleasePython=$Arguments.ReleasePython;BackupRoot=$Arguments.BackupRoot;PreparedReleaseManifest=$Arguments.PreparedReleaseManifest;ExpectedOldHead=$Arguments.ExpectedOldHead;ExpectedReleaseHead=$Arguments.ExpectedReleaseHead}
}
function New-SimulationExecutionContext {
    param([hashtable]$Arguments)
    $root=[IO.Path]::GetFullPath($Arguments.SimulationRoot);$app=Join-Path $root 'production\streamlit_opensea_sales\app_opensea_sales.py';Assert-SimulationTarget $root ([int]$Arguments.SimulationPort) $app|Out-Null
    $old='old';$release='release';if($Arguments.ExpectedOldHead){$old=$Arguments.ExpectedOldHead};if($Arguments.ExpectedReleaseHead){$release=$Arguments.ExpectedReleaseHead}
    return [pscustomobject]@{Mode='SIMULATION';Root=$root;RuntimeRoot=(Join-Path $root 'runtime');AppPath=$app;Port=([int]$Arguments.SimulationPort);EnvPath=(Join-Path $root 'production\.env');DataRoot=(Join-Path $root 'production\streamlit_opensea_sales\data_opensea_sales');RepoRoot=(Join-Path $root 'production');ReleaseRoot=(Join-Path $root 'release');ReleasePython=$Arguments.ReleasePython;BackupRoot=(Join-Path $root 'backups');PreparedReleaseManifest=$Arguments.PreparedReleaseManifest;ExpectedOldHead=$old;ExpectedReleaseHead=$release}
}
