function Get-8502Process {
    $c=Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort 8502 -State Listen -ErrorAction SilentlyContinue|Select-Object -First 1
    if(-not $c){return $null};$p=Get-CimInstance Win32_Process -Filter ('ProcessId='+$c.OwningProcess);if(-not$p -or $p.CommandLine -notmatch '(?i)app_opensea_sales\.py' -or $p.CommandLine -match '(?i)app_gaming_marketplace\.py' -or $p.CommandLine -notmatch [regex]::Escape($script:ExpectedRoot)){throw '8502_PROCESS_IDENTITY_FAILED'};return $p
}
