function Invoke-ChildProcess {
    param([string]$FilePath,[string[]]$Arguments,[string]$WorkingDirectory,[int]$TimeoutSeconds=900,[hashtable]$Environment=@{},[string]$LogPath)
    $psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=$FilePath;$psi.WorkingDirectory=$WorkingDirectory;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.Arguments=(($Arguments|ForEach-Object{if($_ -match '[\s"]'){'"'+($_ -replace '(\\*)\"','$1$1\"')+'"'}else{$_}})-join ' ');foreach($k in $Environment.Keys){$psi.EnvironmentVariables[$k]=[string]$Environment[$k]};$p=New-Object Diagnostics.Process;$p.StartInfo=$psi;if(-not$p.Start()){throw ('CHILD_START_FAILED:'+ $FilePath)};$o=$p.StandardOutput.ReadToEndAsync();$e=$p.StandardError.ReadToEndAsync();if(-not$p.WaitForExit($TimeoutSeconds*1000)){try{$p.Kill()}catch{};throw ('CHILD_TIMEOUT:'+ $FilePath)};$p.WaitForExit();$stdout=$o.Result;$stderr=$e.Result;if($LogPath){Write-AtomicText $LogPath ($stdout+[Environment]::NewLine+$stderr)};if($p.ExitCode -ne 0){throw ('CHILD_COMMAND_FAILED:'+ $FilePath+':'+$p.ExitCode)};return [pscustomobject]@{Pid=$p.Id;ExitCode=$p.ExitCode;StdOut=$stdout;StdErr=$stderr}
}
function Invoke-RefreshAdapter([object]$Context,[string]$Name,[string]$Python,[string[]]$Arguments,[string]$WorkingDirectory){if($Context.Mode -eq 'SIMULATION'){Add-Content (Join-Path $Context.Root 'refresh.commands.log') $Name;return};Invoke-ChildProcess $Python $Arguments $WorkingDirectory 1800 @{}|Out-Null}

function Invoke-BackupCore {
    param([object]$Context,[switch]$Execute)
    Assert-Context $Context|Out-Null
    if(-not$Execute){Write-KV 'MODE' 'DRY_RUN';Write-KV 'TARGET_ROOT' $Context.Root;Write-KV 'TARGET_PORT' $Context.Port;Write-KV 'BACKUP_MANIFEST_SCHEMA_VERSION' 2;Write-KV 'BACKUP_SET_VALID' 'YES';Write-KV 'MUTATION_EXECUTED' 'NO';return}
    Set-ContextPhase $Context 'BACKUP_VALIDATE';$head=$Context.ExpectedOldHead;$branch='main';if($Context.Mode -eq 'PRODUCTION'){$head=(& git -c ('safe.directory='+$Context.Root) -C $Context.Root rev-parse HEAD).Trim();$branch=(& git -c ('safe.directory='+$Context.Root) -C $Context.Root branch --show-current).Trim();if(((& git -c ('safe.directory='+$Context.Root) -C $Context.Root status --porcelain)-join '') -ne ''){throw 'PRODUCTION_WORKTREE_NOT_CLEAN'};$p=Get-8502Process;if(-not$p){throw '8502_PROCESS_NOT_FOUND'};Assert-ProcessIdentity $p $Context};if(-not(Test-Path $Context.EnvPath -PathType Leaf)){throw 'PRODUCTION_ENV_MISSING'};$processPid=0;$processExe='simulation';$processCmd='simulation app_opensea_sales.py';if($Context.Mode -eq 'PRODUCTION'){$processPid=$p.ProcessId;$processExe=$p.ExecutablePath;$processCmd=$p.CommandLine;$tools=Get-PostgresTools;foreach($n in @('pg_dump','pg_restore','psql')){if(-not$tools.ContainsKey($n)){throw ('POSTGRES_TOOL_MISSING:'+ $n)}};Get-DatabaseEnvironment $Context.EnvPath -Required|Out-Null}
    $stamp=Get-Date -Format yyyyMMdd_HHmmss;$short=$head;if($head.Length -gt 8){$short=$head.Substring(0,8)};$out=Join-Path $Context.BackupRoot ($stamp+'_'+$short);New-Item -ItemType Directory -Path $out -Force|Out-Null;$m=[ordered]@{manifest_version=2;created_at=(Get-Date).ToUniversalTime().ToString('o');target_root=$Context.Root;target_port=$Context.Port;target_app=$Context.AppPath;old_git_head=$head;old_git_branch=$branch;old_git_clean=$true;old_process_pid=$processPid;old_process_executable=$processExe;old_process_command_line_sanitized=$processCmd;old_app_path=$Context.AppPath;old_port=$Context.Port;old_runtime_root=$Context.RuntimeRoot;env_backup_relative_path='.env';git_bundle_relative_path='production.bundle';db_dump_relative_path='production.dump';db_dump_format='custom';db_dump_validation='PENDING';dynamic_artifacts=@();active_runtime_existed=$false;production_refresh_tasks=@();backup_complete=$false}
    if($Context.Mode -eq 'SIMULATION'){Set-Content (Join-Path $out 'production.bundle') 'sandbox bundle';Copy-Item $Context.EnvPath (Join-Path $out '.env');Set-Content (Join-Path $out 'production.dump') 'sandbox custom dump';$m.db_dump_validation='PASS'}else{$null=& git -c ('safe.directory='+$Context.Root) -C $Context.Root bundle create (Join-Path $out 'production.bundle') HEAD 2>&1;if($LASTEXITCODE -ne 0){throw 'GIT_BUNDLE_CREATE_FAILED'};Copy-Item $Context.EnvPath (Join-Path $out '.env');$env=Get-DatabaseEnvironment $Context.EnvPath -Required;Invoke-ChildProcess $tools.pg_dump @('--format=custom','--file',(Join-Path $out 'production.dump')) $Context.Root 1800 $env|Out-Null;Invoke-ChildProcess $tools.pg_restore @('--list',(Join-Path $out 'production.dump')) $Context.Root 300 $env|Out-Null;$m.db_dump_validation='PASS'}
    $m.env_sha256=Get-Sha256 (Join-Path $out '.env');$m.git_bundle_sha256=Get-Sha256 (Join-Path $out 'production.bundle');$m.db_dump_sha256=Get-Sha256 (Join-Path $out 'production.dump')
    foreach($d in Get-DynamicArtifactDefinitions $Context){$a=[ordered]@{relative_path=$d.RelativePath;existed_before=(Test-Path $d.Path -PathType Leaf)};if($a.existed_before){$rel='artifacts\'+[IO.Path]::GetFileName($d.Path);New-Item (Join-Path $out 'artifacts') -ItemType Directory -Force|Out-Null;Copy-Item $d.Path (Join-Path $out $rel);$a.backup_relative_path=$rel;$a.sha256_before=Get-Sha256 $d.Path;$a.size_bytes=(Get-Item $d.Path).Length};$m.dynamic_artifacts+=,$a}
    $active=Join-Path $Context.RuntimeRoot 'ACTIVE_RUNTIME.json';if(Test-Path $active -PathType Leaf){New-Item (Join-Path $out 'runtime') -ItemType Directory -Force|Out-Null;Copy-Item $active (Join-Path $out 'runtime\ACTIVE_RUNTIME.json');$m.active_runtime_existed=$true;$m.active_runtime_backup_relative_path='runtime\ACTIVE_RUNTIME.json';$m.active_runtime_sha256=Get-Sha256 $active}
    foreach($name in $script:ManagedTasks){$a=[ordered]@{task_name=$name;existed_before=$false};if($Context.Mode -eq 'SIMULATION'){$tp=Join-Path $Context.Root 'tasks.json';if(Test-Path $tp){$tasks=Get-Content $tp -Raw|ConvertFrom-Json;if($tasks.PSObject.Properties.Name -contains $name){$a.existed_before=$true;$a.state=$tasks.$name}}}else{$t=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue;if($t){$rel='tasks\'+$name+'.xml';New-Item (Join-Path $out 'tasks') -ItemType Directory -Force|Out-Null;Write-AtomicText (Join-Path $out $rel) (Export-ScheduledTask -TaskName $name -ErrorAction Stop);$a.existed_before=$true;$a.exported_xml_relative_path=$rel;$a.xml_sha256=Get-Sha256 (Join-Path $out $rel);$a.enabled=($t.State -ne 'Disabled')}};$m.production_refresh_tasks+=,$a}
    $m.backup_complete=$true;$manifestPath=Join-Path $out 'BACKUP_MANIFEST.json';Write-AtomicJson $manifestPath $m;Write-KV 'BACKUP_MANIFEST_SCHEMA_VERSION' 2;Write-KV 'BACKUP_MANIFEST_PATH' $manifestPath;Write-KV 'BACKUP_RESULT' 'PASS';return [pscustomobject]@{Pass=$true;ManifestPath=$manifestPath}
}

function Invoke-DerivedRefreshCore {
    param([object]$Context,[switch]$Execute)
    Assert-Context $Context|Out-Null;if(-not$Execute){Write-KV 'MODE' 'DRY_RUN';Write-KV 'DERIVED_REFRESH_PLAN' 'PASS';Write-KV 'MUTATION_EXECUTED' 'NO';return};Set-ContextPhase $Context 'DERIVED_REFRESH';$d=Get-DynamicArtifactDefinitions $Context
