    foreach($i in 0..2){if(-not(Test-Path $d[$i].Path -PathType Leaf) -or (Get-Item $d[$i].Path).Length -le 0){throw 'DERIVED_OUTPUT_MISSING'}};Write-KV 'DERIVED_MARKET_PERIOD' 'PASS';Write-KV 'DERIVED_MARKET_EXPANSION' 'PASS';Write-KV 'DERIVED_TRADER_ANALYTICS' 'PASS';Write-KV 'DERIVED_REFRESH' 'PASS';return [pscustomobject]@{Pass=$true}
