function Get-DesiredTaskDefinition([object]$Context,[string]$Name){$derived=$Name -eq $script:ManagedTasks[0];$minutes=60;$sn='refresh_production_metadata.ps1';$approval='REFRESH_OTG_METADATA_8502';if($derived){$minutes=15;$sn='refresh_production_derived.ps1';$approval='REFRESH_OTG_DERIVED_8502'};$q=[char]34;$path=Join-Path $Context.Root ('ops\production\'+$sn);return [ordered]@{task_name=$Name;executable='PowerShell.exe';arguments=('-NoProfile -ExecutionPolicy Bypass -File '+$q+$path+$q+' -Execute -ApprovalPhrase '+$approval+' -ReleasePython '+$q+$Context.ReleasePython+$q);working_directory=$Context.Root;interval_minutes=$minutes;multiple_instances='IgnoreNew';start_when_available=$true;principal='SYSTEM';run_level='Highest';enabled=$true}}
