function Invoke-TaskConfigurationCore {
    param([object]$Context,[switch]$Execute)
    Assert-Context $Context|Out-Null;if(-not$Execute){Write-KV 'MODE' 'DRY_RUN';Write-KV 'TASK_CONFIGURATION_PLAN' 'PASS';Write-KV 'PRODUCTION_REFRESH_TASK_COLLISION_POLICY' 'FAIL_CLOSED';foreach($n in $script:ManagedTasks){Write-KV ('TASK_'+$n) ((Get-DesiredTaskDefinition $Context $n)|ConvertTo-Json -Compress)};Write-KV 'MUTATION_EXECUTED' 'NO';return};Set-ContextPhase $Context 'TASK_CONFIGURATION'
    if($Context.Mode -eq 'SIMULATION'){$old=$null;$tp=Join-Path $Context.Root 'tasks.json';if(Test-Path $tp){$old=Get-Content $tp -Raw|ConvertFrom-Json};$new=@{};foreach($n in $script:ManagedTasks){$d=Get-DesiredTaskDefinition $Context $n;if($old -and $old.PSObject.Properties.Name -contains $n -and -not(Test-TaskDefinitionMatch $old.$n $d)){throw ('TASK_COLLISION:'+ $n)};$new[$n]=[pscustomobject]$d};Write-AtomicJson (Join-Path $Context.Root 'tasks.json') $new}else{foreach($n in $script:ManagedTasks){$d=Get-DesiredTaskDefinition $Context $n;$existing=Get-ScheduledTask -TaskName $n -ErrorAction SilentlyContinue;if($existing){$a=$existing.Actions|Select-Object -First 1;$set=$existing.Settings;if(\"$($a.Execute)\" -notmatch '(?i)power' -or \"$($a.Arguments)\" -ne $d.arguments -or \"$($a.WorkingDirectory)\" -ne $d.working_directory -or \"$($set.MultipleInstances)\" -ne 'IgnoreNew' -or -not $set.StartWhenAvailable){throw ('TASK_COLLISION:'+ $n)};continue};$act=New-ScheduledTaskAction -Execute $d.executable -Argument $d.arguments -WorkingDirectory $d.working_directory;$tr=New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes $d.interval_minutes) -RepetitionDuration (New-TimeSpan -Days 3650);$set=New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -StartWhenAvailable;Register-ScheduledTask -TaskName $n -Action $act -Trigger $tr -Settings $set -RunLevel Highest -User SYSTEM -ErrorAction Stop|Out-Null}}
    Write-KV 'TASK_CONFIGURATION' 'PASS';Write-KV 'PRODUCTION_REFRESH_TASKS' 'PASS';return [pscustomobject]@{Pass=$true}
}

function Read-BackupManifest([string]$Path,[object]$Context){if(-not(Test-Path $Path -PathType Leaf)){throw 'BACKUP_MANIFEST_MISSING'};$m=Get-Content $Path -Raw|ConvertFrom-Json;if($m.manifest_version -ne 2 -or -not$m.backup_complete -or $m.target_root -ne $Context.Root -or [int]$m.target_port -ne $Context.Port -or $m.target_app -ne $Context.AppPath){throw 'BACKUP_MANIFEST_INVALID'};$base=Split-Path $Path -Parent;foreach($pair in @(@('env_backup_relative_path','env_sha256'),@('git_bundle_relative_path','git_bundle_sha256'),@('db_dump_relative_path','db_dump_sha256'))){$p=Join-Path $base $m.($pair[0]);if(-not(Test-Path $p -PathType Leaf) -or (Get-Sha256 $p) -ne [string]$m.($pair[1])){throw 'BACKUP_MANIFEST_HASH_MISMATCH'}};if($m.db_dump_format -ne 'custom' -or $m.db_dump_validation -ne 'PASS'){throw 'BACKUP_DB_VALIDATION_MISSING'};if(@($m.dynamic_artifacts).Count -ne 6 -or @($m.production_refresh_tasks).Count -ne 2){throw 'BACKUP_MANIFEST_STATE_INCOMPLETE'};foreach($a in @($m.dynamic_artifacts)){if($a.existed_before){$p=Join-Path $base $a.backup_relative_path;if(-not(Test-Path $p -PathType Leaf) -or (Get-Sha256 $p) -ne [string]$a.sha256_before){throw 'BACKUP_ARTIFACT_HASH_MISMATCH'}}};return [pscustomobject]@{Manifest=$m;Base=$base}}
function Set-FailClosedEnv([object]$Context){$lines=@();if(Test-Path $Context.EnvPath){$lines=Get-Content $Context.EnvPath};$updates=@{GUNZSCOPE_SUPPLY_SOURCE='v3';OTG_ANALYTICS_WRITES_ENABLED='false';OTG_SITE_ANALYTICS_ENABLED='false';OTG_PRODUCT_EVENTS_ENABLED='false';OTG_FEEDBACK_WRITES_ENABLED='false';OTG_FEEDBACK_TELEGRAM_ENABLED='false'};$seen=@{};$new=@();foreach($l in $lines){if($l -match '^\s*([^#=][^=]*)='){$k=$Matches[1].Trim();if($updates.ContainsKey($k)){$new+=($k+'='+$updates[$k]);$seen[$k]=$true}else{$new+=$l}}else{$new+=$l}};foreach($k in $updates.Keys){if(-not$seen.ContainsKey($k)){$new+=($k+'='+$updates[$k])}};Write-AtomicText $Context.EnvPath (($new -join [Environment]::NewLine)+[Environment]::NewLine)}
function Invoke-ContextMigrations([object]$Context){Assert-AllowedMigrationSet $script:AllowedMigrations|Out-Null;if($Context.Mode -eq 'SIMULATION'){Set-Content (Join-Path $Context.Root 'migrations.log') ($script:AllowedMigrations -join [Environment]::NewLine);return};$tools=Get-PostgresTools;if(-not$tools.ContainsKey('psql')){throw 'PSQL_MISSING'};$env=Get-DatabaseEnvironment $Context.EnvPath -Required;foreach($m in $script:AllowedMigrations){$p=Join-Path $Context.RepoRoot $m;if(-not(Test-Path $p)){throw ('MIGRATION_MISSING:'+ $m)};Invoke-ChildProcess $tools.psql @('-X','-v','ON_ERROR_STOP=1','-f',$p) $Context.Root 300 $env|Out-Null}}
function Invoke-ContextGitFastForward([object]$Context,[string]$ReleaseHead){if($Context.Mode -eq 'SIMULATION'){$s=Get-Content (Join-Path $Context.Root 'simulation_state.json') -Raw|ConvertFrom-Json;$s.current_head=$ReleaseHead;Write-AtomicJson (Join-Path $Context.Root 'simulation_state.json') $s;return};& git -c ('safe.directory='+$Context.Root) -C $Context.Root fetch origin main;if($LASTEXITCODE -ne 0){throw 'GIT_FETCH_FAILED'};& git -c ('safe.directory='+$Context.Root) -C $Context.Root merge --ff-only origin/main;if($LASTEXITCODE -ne 0){throw 'GIT_FAST_FORWARD_FAILED'}}
function Invoke-ContextGitReset([object]$Context,[string]$OldHead){if($Context.Mode -eq 'SIMULATION'){$s=Get-Content (Join-Path $Context.Root 'simulation_state.json') -Raw|ConvertFrom-Json;$s.current_head=$OldHead;Write-AtomicJson (Join-Path $Context.Root 'simulation_state.json') $s;return};& git -c ('safe.directory='+$Context.Root) -C $Context.Root reset --hard $OldHead;if($LASTEXITCODE -ne 0){throw 'GIT_ROLLBACK_FAILED'}}
function Invoke-ContextStopProcess([object]$Context){if($Context.Mode -eq 'SIMULATION'){$s=Get-Content (Join-Path $Context.Root 'simulation_state.json') -Raw|ConvertFrom-Json;$s.process='stopped';Write-AtomicJson (Join-Path $Context.Root 'simulation_state.json') $s;return};$p=Get-8502Process;if(-not$p){throw '8502_PROCESS_NOT_FOUND'};Assert-ProcessIdentity $p $Context;Stop-Process -Id $p.ProcessId -Force;for($i=0;$i-lt 60;$i++){if(-not(Get-8502Process)){return};Start-Sleep -Milliseconds 500};throw '8502_DID_NOT_STOP'}
function Invoke-ContextStartProcess([object]$Context,[string]$Python,[string]$LogPath,[switch]$Old){if($Context.Mode -eq 'SIMULATION'){$s=Get-Content (Join-Path $Context.Root 'simulation_state.json') -Raw|ConvertFrom-Json;$state='new-healthy';if($Old){$state='old-healthy'}elseif($s.fail_new_health){$state='new-failed'};$s.process=$state;Write-AtomicJson (Join-Path $Context.Root 'simulation_state.json') $s;return [pscustomobject]@{Pid=18502}};if(-not(Test-Path $Python -PathType Leaf)){throw 'RUNTIME_PYTHON_MISSING'};$args=@('-m','streamlit','run',$Context.AppPath,'--server.address','127.0.0.1','--server.port','8502','--server.fileWatcherType','none','--browser.gatherUsageStats','false');$safe=Get-SafeEnv $Context.EnvPath;$oldEnv=@{};foreach($k in $safe.Keys){$oldEnv[$k]=[Environment]::GetEnvironmentVariable($k,'Process');[Environment]::SetEnvironmentVariable($k,[string]$safe[$k],'Process')};try{$p=Start-Process -FilePath $Python -ArgumentList $args -WorkingDirectory (Split-Path $Context.AppPath) -RedirectStandardOutput $LogPath -RedirectStandardError ($LogPath+'.err') -PassThru -WindowStyle Hidden}finally{foreach($k in $safe.Keys){[Environment]::SetEnvironmentVariable($k,$oldEnv[$k],'Process')}};return $p}

function Invoke-DeployCore {
    param([object]$Context,[switch]$Execute)
    Assert-Context $Context|Out-Null;if(-not$Execute){Write-KV 'MODE' 'DRY_RUN';Write-KV 'DEPLOY_PLAN' 'PASS';Write-KV 'MAIN_PROMOTION_REQUIRED' 'YES';Write-KV 'MUTATION_EXECUTED' 'NO';return};Set-ContextPhase $Context 'DEPLOY_VALIDATE'
    if($Context.Mode -eq 'PRODUCTION'){if(-not$Context.ExpectedOldHead -or -not$Context.ExpectedReleaseHead -or -not$Context.ReleasePython -or -not$Context.PreparedReleaseManifest){throw 'DEPLOY_INPUTS_MISSING'};$actual=(& git -c ('safe.directory='+$Context.Root) -C $Context.Root rev-parse HEAD).Trim();if($actual -ne $Context.ExpectedOldHead){throw 'EXPECTED_OLD_HEAD_MISMATCH'};if(((& git -c ('safe.directory='+$Context.Root) -C $Context.Root status --porcelain)-join '') -ne ''){throw 'PRODUCTION_WORKTREE_NOT_CLEAN'};$main=(& git -c ('safe.directory='+$Context.Root) -C $Context.Root rev-parse origin/main).Trim();if($main -ne $Context.ExpectedReleaseHead){throw 'MAIN_PROMOTION_REQUIRED'};if(-not(Test-Path $Context.ReleaseRoot -PathType Container)){throw 'RELEASE_ROOT_MISSING'}}else{$s=Get-Content (Join-Path $Context.Root 'simulation_state.json') -Raw|ConvertFrom-Json;if($s.main_head -ne $Context.ExpectedReleaseHead){throw 'MAIN_PROMOTION_REQUIRED'}};$null=Read-BackupManifest $Context.PreparedReleaseManifest $Context;Assert-AllowedMigrationSet $script:AllowedMigrations|Out-Null;$stopped=$false
    try{Set-ContextPhase $Context 'DEPLOY_STOP';Invoke-ContextStopProcess $Context;$stopped=$true;Set-ContextPhase $Context 'DEPLOY_FAST_FORWARD';Invoke-ContextGitFastForward $Context $Context.ExpectedReleaseHead;Set-ContextPhase $Context 'DEPLOY_ENV';Set-FailClosedEnv $Context;Set-ContextPhase $Context 'DEPLOY_MIGRATIONS';Invoke-ContextMigrations $Context;Set-ContextPhase $Context 'DEPLOY_DERIVED';Invoke-DerivedRefreshCore $Context -Execute|Out-Null;Set-ContextPhase $Context 'DEPLOY_METADATA';Invoke-MetadataRefreshCore $Context -Execute|Out-Null;Set-ContextPhase $Context 'DEPLOY_READERS';foreach($d in Get-DynamicArtifactDefinitions $Context){if(-not(Test-Path $d.Path -PathType Leaf)){throw 'DEPLOY_ARTIFACT_VALIDATION_FAILED'}};Set-ContextPhase $Context 'DEPLOY_START';$new=Invoke-ContextStartProcess $Context $Context.ReleasePython (Join-Path $Context.Root 'deployment.log');Set-ContextPhase $Context 'DEPLOY_HEALTH';$healthy=$false;if($Context.Mode -eq 'SIMULATION'){$healthy=(Get-Content (Join-Path $Context.Root 'simulation_state.json') -Raw|ConvertFrom-Json).process -eq 'new-healthy'}else{$healthy=Invoke-HealthCheck 8502 60};if(-not$healthy){throw 'NEW_PRODUCTION_HEALTH_FAILED'};Set-ContextPhase $Context 'DEPLOY_TASKS';Invoke-TaskConfigurationCore $Context -Execute|Out-Null;Write-AtomicJson (Join-Path $Context.Root 'DEPLOYMENT_RECEIPT.json') ([ordered]@{old_head=$Context.ExpectedOldHead;new_head=$Context.ExpectedReleaseHead;new_pid=$new.Pid;sql_migration_count=3;dynamic_artifact_count=6;health='PASS'});Write-KV 'DEPLOY_RESULT' 'PASS';return [pscustomobject]@{Pass=$true}}catch{if($stopped){Write-KV 'DEPLOY_FAILURE_AFTER_DOWNTIME_STARTED' 'YES';try{Invoke-RollbackCore $Context -Execute -Automatic|Out-Null}catch{Write-KV 'ROLLBACK_FAILURE' $_.Exception.Message}};throw}
}
function Invoke-HealthCheck([int]$Port,[int]$TimeoutSeconds=60){$until=(Get-Date).AddSeconds($TimeoutSeconds);do{try{$r=Invoke-WebRequest ('http://127.0.0.1:'+ $Port) -UseBasicParsing -TimeoutSec 5;if($r.StatusCode -ge 200 -and $r.StatusCode -lt 500){return $true}}catch{};Start-Sleep -Milliseconds 500}while((Get-Date)-lt $until);return $false}
function Invoke-RollbackCore {
    param([object]$Context,[switch]$Execute,[switch]$Automatic)
    Assert-Context $Context|Out-Null;if(-not$Execute){Write-KV 'MODE' 'DRY_RUN';Write-KV 'ROLLBACK_PLAN' 'PASS';Write-KV 'DB_SCHEMA_ROLLBACK' 'NOT_AUTOMATIC';Write-KV 'REMOTE_MAIN_ROLLBACK' 'NOT_AUTOMATIC';Write-KV 'MUTATION_EXECUTED' 'NO';return};Set-ContextPhase $Context 'ROLLBACK_VALIDATE';$b=Read-BackupManifest $Context.PreparedReleaseManifest $Context;$m=$b.Manifest;Set-ContextPhase $Context 'ROLLBACK_STOP';if($Context.Mode -eq 'SIMULATION'){Invoke-ContextStopProcess $Context}else{$p=Get-8502Process;if($p){Assert-ProcessIdentity $p $Context;Invoke-ContextStopProcess $Context}};Set-ContextPhase $Context 'ROLLBACK_GIT';Invoke-ContextGitReset $Context ([string]$m.old_git_head);Set-ContextPhase $Context 'ROLLBACK_ENV';Copy-Item (Join-Path $b.Base $m.env_backup_relative_path) $Context.EnvPath -Force;if((Get-Sha256 $Context.EnvPath) -ne [string]$m.env_sha256){throw 'ROLLBACK_ENV_HASH_MISMATCH'};Set-ContextPhase $Context 'ROLLBACK_ARTIFACTS';foreach($a in @($m.dynamic_artifacts)){$target=(Get-DynamicArtifactDefinitions $Context|Where-Object RelativePath -eq $a.relative_path).Path;if($a.existed_before){Copy-Item (Join-Path $b.Base $a.backup_relative_path) $target -Force;if((Get-Sha256 $target) -ne [string]$a.sha256_before){throw 'ROLLBACK_ARTIFACT_STATE_MISMATCH'}}elseif(Test-Path $target -PathType Leaf){Remove-Item -LiteralPath $target -Force}};Set-ContextPhase $Context 'ROLLBACK_TASKS';if($Context.Mode -eq 'SIMULATION'){$old=@{};foreach($t in @($m.production_refresh_tasks)){if($t.existed_before){$old[$t.task_name]=$t.state}};Write-AtomicJson (Join-Path $Context.Root 'tasks.json') $old}else{foreach($n in $script:ManagedTasks){$e=@($m.production_refresh_tasks|Where-Object task_name -eq $n)[0];$existing=Get-ScheduledTask -TaskName $n -ErrorAction SilentlyContinue;if($e.existed_before){Register-ScheduledTask -TaskName $n -Xml (Get-Content (Join-Path $b.Base $e.exported_xml_relative_path) -Raw) -Force|Out-Null}elseif($existing){Unregister-ScheduledTask -TaskName $n -Confirm:$false}}};Set-ContextPhase $Context 'ROLLBACK_RUNTIME';$active=Join-Path $Context.RuntimeRoot 'ACTIVE_RUNTIME.json';if($m.active_runtime_existed){Copy-Item (Join-Path $b.Base $m.active_runtime_backup_relative_path) $active -Force}elseif(Test-Path $active -PathType Leaf){Remove-Item -LiteralPath $active -Force};Set-ContextPhase $Context 'ROLLBACK_START';$py=$Context.ReleasePython;if($m.old_process_executable -and $m.old_process_executable -ne 'simulation'){$py=$m.old_process_executable};$old=Invoke-ContextStartProcess $Context $py (Join-Path $Context.Root 'rollback.log') -Old;Set-ContextPhase $Context 'ROLLBACK_HEALTH';$healthy=$true;if($Context.Mode -eq 'PRODUCTION'){$healthy=Invoke-HealthCheck 8502 60};if(-not$healthy){throw 'ROLLBACK_OLD_APP_HEALTH_FAILED'};Write-KV 'DB_SCHEMA_ROLLBACK' 'NOT_AUTOMATIC';Write-KV 'REMOTE_MAIN_ROLLBACK' 'NOT_AUTOMATIC';Write-KV 'ROLLBACK_RESULT' 'PASS';return [pscustomobject]@{Pass=$true}
}
